def second_largest(nums):
    if len(nums) < 2:
        return None  # Not enough elements to find a second largest

    max1 = max2 = float('-inf')  # Initialize with negative infinity

    for num in nums:
        if num > max1:
            max2 = max1
            max1 = num
        elif num != max1 and num > max2:
            max2 = num

    return max2

