def temp_range(temps):
    if len(temps) == 0:
        return 0
    max_temp = temps[0]
    min_temp = temps[0]
    for temp in temps:
        if temp > max_temp:
            max_temp = temp
        if temp < min_temp:
            min_temp = temp
    return max_temp - min_temp

print(temp_range([23, 19, 31, 22, 18]))
