def binary_search(nums, target):
    # Check if the list is empty
    if not nums:
        return -1

    # Check if the list has only one element
    if len(nums) == 1:
        return 0 if nums[0] == target else -1

    # Binary search algorithm
    left, right = 0, len(nums) - 1

    while left <= right:
        mid = (left + right) // 2

        if nums[mid] == target:
            return mid
        elif nums[mid] < target:
            left = mid + 1
        else:
            right = mid - 1

    # Target not found
    return -1

