def is_leap(year):
    # A leap year is exactly divisible by 4 except for end-of-century years
    # which must be divisible by 400. This means that the year 2000 was a leap year,
    # although 1900 was not.
    if year % 4 == 0:
        if year % 100 == 0:
            if year % 400 == 0:
                return True
            else:
                return False
        else:
            return True
    else:
        return False

